const { spawn } = require('child_process');
const fs = require('fs');

const projectDir = 'C:\\Users\\India\\OneDrive\\Desktop\\Foundit_APMM_Assignment';
const pythonExe = 'C:\\Program Files\\Python311\\python.exe';
const userSite = 'C:\\Users\\India\\AppData\\Roaming\\Python\\Python311\\site-packages';
const finalExcel = projectDir + '\\outputs\\fRL_winners.xlsx';

function runCommand(args) {
  return new Promise((resolve) => {
    const child = spawn(pythonExe, args, {
      cwd: projectDir,
      windowsHide: true,
      env: {
        PYTHONPATH: userSite,
        PYTHONUSERBASE: 'C:\\Users\\India\\AppData\\Roaming\\Python',
        SystemRoot: 'C:\\Windows',
        TEMP: 'C:\\Users\\India\\AppData\\Local\\Temp',
        TMP: 'C:\\Users\\India\\AppData\\Local\\Temp'
      }
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', (data) => { stdout += data.toString(); });
    child.stderr.on('data', (data) => { stderr += data.toString(); });
    child.on('close', (code) => { resolve({ code, output: (stdout + '\\n' + stderr).trim() }); });
    child.on('error', (error) => { resolve({ code: 1, output: error.message }); });
  });
}

const pythonCheck = await runCommand(['-c', 'import sys; print(sys.executable); import pandas; print(pandas.__version__)']);

if (pythonCheck.code !== 0) {
  return [{ json: { workflow: 'foundit APMM n8n pipeline', status: 'Failed', reason: 'Python dependency check failed', python_check_output: pythonCheck.output, final_excel_exists: fs.existsSync(finalExcel), github_repo: 'https://github.com/ankit619288/foundit-apmm-assignment', streamlit_app: 'https://foundit-apmm.streamlit.app/' } }];
}

const pipeline = await runCommand(['run_pipeline.py']);
const success = pipeline.code === 0 && pipeline.output.toLowerCase().includes('pipeline completed') && fs.existsSync(finalExcel);

return [{
  json: {
    workflow: 'foundit APMM n8n pipeline',
    status: success ? 'Success' : 'Failed',
    pipeline_ran: pipeline.code === 0,
    final_excel_exists: fs.existsSync(finalExcel),
    final_excel: finalExcel,
    github_repo: 'https://github.com/ankit619288/foundit-apmm-assignment',
    streamlit_app: 'https://foundit-apmm.streamlit.app/',
    python_check_output: pythonCheck.output,
    pipeline_output: pipeline.output
  }
}];
